Reproducer: 
```
define <2 x i8> @byte2() {
  ret <2 x i8> zeroinitializer
}
```

patch:
commit fda2fea3d161e07ec3a8441359f761ce9dd9a977
Author: Manasij Mukherjee <manasij7479@gmail.com>
Date:   Fri Oct 4 15:15:30 2024 -0600

    [NVPTX] Promote v2i8 to v2i16 (#111189)

    Promote v2i8 to v2i16, fixes a crash.
    Re-enable a test in NVPTX/vector-returns.ll

    https://github.com/llvm/llvm-project/issues/104864

diff --git a/llvm/lib/Target/NVPTX/NVPTXISelLowering.cpp b/llvm/lib/Target/NVPTX/NVPTXISelLowering.cpp
index 8718b7890bf5..57bc5fe0ac36 100644
--- a/llvm/lib/Target/NVPTX/NVPTXISelLowering.cpp
+++ b/llvm/lib/Target/NVPTX/NVPTXISelLowering.cpp
@@ -236,6 +236,10 @@ static void ComputePTXValueVTs(const TargetLowering &TLI, const DataLayout &DL,
         // v*i8 are formally lowered as v4i8
         EltVT = MVT::v4i8;
         NumElts = (NumElts + 3) / 4;
+      } else if (EltVT.getSimpleVT() == MVT::i8 && NumElts == 2) {
+        // v2i8 is promoted to v2i16
+        NumElts = 1;
+        EltVT = MVT::v2i16;
       }
       for (unsigned j = 0; j != NumElts; ++j) {
         ValueVTs.push_back(EltVT);

